const csv = $input.first().json.csv_data;

if (typeof csv !== 'string' || !csv.trim()) {
  throw new Error('CSV vazio ou inválido.');
}

const linhas = csv.trim().split(/\r?\n/);
const cabecalho = linhas.shift().split(',');

const investimentos = linhas
  .filter(linha => linha.trim())
  .map(linha => {
    const valores = linha.split(',');

    const registro = Object.fromEntries(
      cabecalho.map((coluna, indice) => [
        coluna.trim(),
        valores[indice]?.trim()
      ])
    );

    return {
      perfil: registro.perfil,
      produto: registro.produto,
      minimo: Number(registro.minimo),
      rentabilidade: registro.rentabilidade
    };
  });

return investimentos.map(investimento => ({
  json: investimento
}));

const clientes = $('Webhook').first().json.body.clientes;
const investimentos = $input.all().map(item => item.json);

function converterSaldo(valor) {
  if (typeof valor === 'number') return valor;

  const texto = String(valor)
    .replace(/R\$\s?/g, '')
    .replace(/\./g, '')
    .replace(',', '.')
    .trim();

  const saldo = Number(texto);

  if (!Number.isFinite(saldo) || saldo < 0) {
    throw new Error(`Saldo inválido: ${valor}`);
  }

  return saldo;
}

if (!Array.isArray(clientes)) {
  throw new Error('Lista de clientes não encontrada.');
}

const resultado = clientes.map(cliente => {
  const saldo = converterSaldo(cliente.saldo);

  const produtosCompativeis = investimentos.filter(
    investimento =>
      investimento.perfil === cliente.perfil &&
      Number.isFinite(investimento.minimo) &&
      saldo >= investimento.minimo
  );

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      produtos_compativeis: produtosCompativeis,
      total_produtos: produtosCompativeis.length
    }
  };
});

return resultado;

const clientes = $input.all();

return clientes.map(item => {
  const cliente = item.json;

  const produtos = cliente.produtos_compativeis || [];

  const listaProdutos = produtos.length
    ? produtos.map(p =>
        `• ${p.produto} (mínimo: R$ ${p.minimo.toLocaleString('pt-BR')})`
      ).join('\n')
    : 'Nenhum produto disponível para os critérios informados.';

  const mensagem = `Olá, ${cliente.nome}!

Preparamos uma simulação educativa com base no seu perfil ${cliente.perfil}.

Opções compatíveis com os critérios informados:

${listaProdutos}

Estas informações são apenas ilustrativas e não constituem recomendação de investimento. A adequação real depende de outros fatores, incluindo objetivos, riscos e horizonte de investimento.

Atenciosamente,
Assistente de Investimentos | DIO`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      total_produtos: produtos.length,
      mensagem
    }
  };
});

const respostaIA = $input.first().json;

// Recupera o cliente associado à entrada do Gemini
const cliente = $('Loop Over Items').first(1, $runIndex).json;

const mensagemIA = respostaIA.content?.parts
  ?.map(parte => parte.text || '')
  .join('\n')
  .trim();

if (!mensagemIA) {
  throw new Error('O Gemini não retornou uma mensagem válida.');
}

return [{
  json: {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    total_produtos: cliente.total_produtos,
    mensagem_original: cliente.mensagem,
    mensagem_ia: mensagemIA,
    modelo: 'gemini-2.5-flash',
    status: 'gerado'
  }
}];

const itens = $input.all();

const clientes = itens.map(item => ({
  nome: item.json.nome,
  email: item.json.email,
  perfil: item.json.perfil,
  total_produtos: item.json.total_produtos,
  mensagem_original: item.json.mensagem_original,
  mensagem_ia: item.json.mensagem_ia,
  modelo: item.json.modelo,
  status: item.json.status
}));

return [{
  json: {
    projeto: "DIO | Assistente de Investimentos - RPA + IA",
    total_clientes: clientes.length,
    data_processamento: new Date().toISOString(),
    clientes
  }
}];
